import { PlaneGeometry, Object3D, AdditiveBlending, Vector2 } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uniform, texture, uv, vec2, vec4, mix, smoothstep, Fn } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Object3D();
  group.position.set(0, 3, 0);

  // --- Texture loading ---
  const textureUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  let textureMap = null;
  let textureLoaded = false;

  ctx.textureLoader.loadTexture(textureUrl).then((tex) => {
    textureMap = tex;
    textureLoaded = true;

    // Apply atlas UV offsets if source rect provided
    if (config.atlasRegion) {
      const { sourceRect } = config.atlasRegion;
      if (sourceRect) {
        const atlasWidth = 512; // Default atlas size
        const atlasHeight = 320;
        const u = sourceRect.x / atlasWidth;
        const v = sourceRect.y / atlasHeight;
        const w = sourceRect.width / atlasWidth;
        const h = sourceRect.height / atlasHeight;
        tex.repeat.set(w, h);
        tex.offset.set(u, v);
      }
    }

    // Update material when texture arrives
    if (material) {
      material.map = tex;
      material.needsUpdate = true;
    }
  });

  // --- Geometry for atlas region ---
  const aspectRatio = 512 / 320; // From source rect dimensions
  const planeWidth = 2.0;
  const planeHeight = planeWidth / aspectRatio;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // --- Material with grain overlay ---
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  // Grain overlay using shader nodes
  const timeNode = uniform(0);
  const grainIntensity = uniform(0.08);

  const grainEffect = Fn(() => {
    const uvNode = uv();
    const grain = vec2(
      uvNode.x * 512,
      uvNode.y * 320
    );
    // Simple pseudo-random grain
    const noise = mix(0.95, 1.05, Math.random());
    const grainAmount = grainIntensity.mul(noise - 0.5);
    return grainAmount;
  });

  // Combine texture with grain
  const baseColor = texture(textureMap || ctx.THREE.Texture.default, uv());
  const grainOffset = grainEffect();
  const finalColor = baseColor.add(vec4(grainOffset, grainOffset, grainOffset, 0));

  material.colorNode = finalColor.rgb;
  material.opacityNode = baseColor.a;

  // Create mesh
  const mesh = new ctx.THREE.Mesh(geometry, material);
  mesh.frustumCulled = false;
  mesh.renderOrder = 0;
  group.add(mesh);

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find(item => item.role === 'headline');

  if (headline) {
    const fontSize = headline.typography?.fontSize || 96;
    const textObj = ctx.fontAtlas.createText(headline.text, {
      fontSize: fontSize * 0.006, // Convert px to scene units
      color: config.colors?.paper || '#e8ecf2',
      align: 'center',
    });
    textObj.position.set(0, 0.6, 0.05);
    textObj.scale.set(0.8, 0.8, 0.8);
    group.add(textObj);
  }

  // --- Engineered gradient surface (subtle dark-to-warm underlay) ---
  const gradientGeom = new PlaneGeometry(planeWidth * 1.1, planeHeight * 1.1);
  const gradientMat = new ctx.THREE.MeshBasicNodeMaterial({
    transparent: true,
    opacity: 0.15,
    depthWrite: false,
    blending: AdditiveBlending,
  });

  // Vertical gradient using shader nodes
  const gradientY = uniform(0);
  const gradientColor = Fn(() => {
    const yPos = uv().y;
    const gradientMix = smoothstep(0.3, 0.7, yPos);
    const bottomColor = vec4(0.09, 0.04, 0.02, 1.0); // Warm dark
    const topColor = vec4(0.15, 0.12, 0.1, 0.8);    // Slightly lighter warm
    return mix(bottomColor, topColor, gradientMix);
  });

  gradientMat.colorNode = gradientColor();

  const gradientMesh = new ctx.THREE.Mesh(gradientGeom, gradientMat);
  gradientMesh.position.set(0, 0, -0.02);
  gradientMesh.renderOrder = -1;
  group.add(gradientMesh);

  // --- Subtle IDLE motion (breathing scale) ---
  const idleTimeline = gsap.timeline({ repeat: -1, yoyo: true });
  idleTimeline.to(mesh.scale, {
    x: 1.02,
    y: 1.02,
    z: 1.02,
    duration: 3.0,
    ease: 'power1.inOut',
  }, 0);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    idleTimeline.kill();
    geometry.dispose();
    material.dispose();
    gradientGeom.dispose();
    gradientMat.dispose();
    if (textureMap) textureMap.dispose();
  };

  // --- Event handlers (none specified, but provide empty for safety) ---
  group.userData.handlers = {};

  return group;
}
